      loadedOfficial: false,
      loadStatus: "libs-rnp-status-load-failed",
      loadErrorReason: "RNP/OpenPGP library failed to load",
      path: "",

      getRNPLibStatus() {
        return {
          min_version: required_version_str,
          loaded_version: "-",
          status: this.loadStatus,
          error: this.loadErrorReason,
          path: this.path,
        };
      },
    };

    loadExternalRNPLib();
    if (!librnp) {
      return dummyRNPLib;
    }

